CREATE TABLE dbo.Contractors (ContractorId INT IDENTITY PRIMARY KEY, ContractorName NVARCHAR(200) NOT NULL UNIQUE, IsActive BIT NOT NULL DEFAULT 1, CreatedDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.ProjectContractor (ProjectId NVARCHAR(100) NOT NULL PRIMARY KEY, ContractorId INT NOT NULL REFERENCES dbo.Contractors(ContractorId), IsLocked BIT NOT NULL DEFAULT 0, AssignedDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Plans (PlanId INT IDENTITY PRIMARY KEY, ProjectId NVARCHAR(100) NOT NULL, PlanNumber INT NOT NULL CHECK(PlanNumber>0), PlanName NVARCHAR(200) NULL, CreatedDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_Plans UNIQUE(ProjectId,PlanNumber));
CREATE TABLE dbo.PlanAssemblies (Id INT IDENTITY PRIMARY KEY, PlanId INT NOT NULL REFERENCES dbo.Plans(PlanId), ModelId NVARCHAR(100) NULL, ObjectRuntimeId INT NULL, AssemblyGuid NVARCHAR(100) NOT NULL, AssemblyName NVARCHAR(300) NULL, AssemblyMark NVARCHAR(100) NULL, Weight DECIMAL(12,3) NULL, Grid NVARCHAR(100) NULL, Tos NVARCHAR(100) NULL, SequenceOrder INT NOT NULL CHECK(SequenceOrder>0), CreatedDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_PlanAssemblies UNIQUE(PlanId,AssemblyGuid), CONSTRAINT UQ_PlanSequence UNIQUE(PlanId,SequenceOrder));
CREATE INDEX IX_PlanAssemblies_PlanId ON dbo.PlanAssemblies(PlanId);
